/* DAYMARK Training: explainable prototype recommendation + a guided, local-only session. */
Object.assign(TRAINING_EXERCISES,{
 sidewalk:{name:'Бокові кроки',group:'Кардіо · координація',pose:'walk',cue:'Крокуй у бік і повертайся, не поспішаючи.',check:'Тримай комфортний темп і вільно дихай.'},
 calf:{name:'Підйоми на носки',group:'Литки · баланс',pose:'step',cue:'Тримайся за опору, піднімайся на носки й повільно опускайся.',check:'Без пружних ривків; опора має бути стійкою.'},
 clamshell:{name:'Розкриття колін лежачи',group:'Сідниці · стабілізація',pose:'bridge',cue:'Ляж на бік із зігнутими колінами. Підніми верхнє коліно, не розвертаючи таз.',check:'Рух невеликий і контрольований.'},
 lateralband:{name:'Бокові кроки з міністрічкою',group:'Сідниці · ноги',pose:'step',cue:'Надінь міністрічку вище колін. Злегка зігни ноги й зроби кілька кроків убік.',check:'Коліна не зводь усередину; обери посильний опір.',swap:'sidewalk'},
 bandpress:{name:'Жим еспандера від грудей',group:'Груди · руки',pose:'push',cue:'Закріпи стрічку позаду надійно, виштовхни руки вперед і повільно поверни.',check:'Перевір кріплення, не прогинай поперек.',swap:'wallpush'},
 dbfloor:{name:'Жим гантелей лежачи на підлозі',group:'Груди · руки',pose:'push',cue:'Ляж на підлогу, зігни коліна. Плавно підніми гантелі над грудьми.',check:'Лікті опускай контрольовано, без удару об підлогу.',swap:'wallpush'},
 dbreverse:{name:'Розведення гантелей у нахилі',group:'Верх спини · плечі',pose:'pull',cue:'З легкими гантелями відведи руки в сторони, не піднімаючи плечі.',check:'Не розгойдуй тулуб; почни з невеликої ваги.',swap:'pullapart'},
 cableface:{name:'Тяга канату до обличчя',group:'Верх спини · плечі',pose:'pull',cue:'Встанови блок приблизно на рівні обличчя. Потягни канат до себе ліктями в сторони.',check:'Не відхиляйся назад і не тягни інерцією.',swap:'pullapart'},
 seatedrow:{name:'Тяга у тренажері з опорою',group:'Спина · руки',pose:'pull',cue:'Налаштуй сидіння та опору. Тягни руків’я ліктями назад.',check:'Не відривай грудну клітку від опори.',swap:'rowband'},
 extension:{name:'Розгинання ніг у тренажері',group:'Передня поверхня стегна',pose:'step',cue:'Налаштуй валик і сидіння. Плавно випрями ноги та опусти.',check:'Не розгинай коліна різко; обери легкий опір.',swap:'sit'},
 bike:{name:'Велотренажер у комфортному темпі',group:'Кардіо · витривалість',pose:'walk',cue:'Налаштуй висоту сидіння. Почни легко, потім тримай темп, у якому можеш говорити.',check:'Не женись за цифрою опору; припини при запамороченні.'},
 breathing:{name:'Спокійне дихання та завершення',group:'Відновлення',pose:'core',cue:'Сповільни рух, вирівняй дихання, дай пульсу поступово заспокоїтися.',check:'Не затримуй дихання й не форсуй глибину вдиху.'},
 posture:{name:'Розкриття грудного відділу',group:'Рухливість · постава',pose:'core',cue:'Сидячи або стоячи, м’яко поверни грудну клітку в бік і повернись.',check:'Не скручуйся через біль у спині.'},
 farmer:{name:'Ходьба з гантелями',group:'Корпус · хват',pose:'walk',cue:'Візьми посильні гантелі й пройдися повільно, зберігаючи рівну поставу.',check:'Не нахиляйся вбік; звільни шлях від перешкод.',swap:'walk'}
});
TRAINING_PLANS.push(
 {id:'home-quiet',name:'Тихе тренування без стрибків',place:'home',goal:'start',gear:'none',level:'beginner',minutes:22,tone:'blue',tag:'Для квартири',items:[['sit','2 × 8–12'],['wallpush','2 × 8–12'],['clamshell','2 × 10 / бік'],['bird','2 × 6 / бік']]},
 {id:'home-low',name:'Легка силова після паузи',place:'home',goal:'strength',gear:'none',level:'beginner',minutes:25,tone:'lime',tag:'Повернення до руху',items:[['sit','2 × 8'],['wallpush','2 × 8'],['bridge','2 × 10'],['calf','2 × 12']]},
 {id:'home-core',name:'Стабільний корпус',place:'home',goal:'strength',gear:'none',level:'all',minutes:25,tone:'violet',tag:'Без скручувань',items:[['bird','2–3 × 8 / бік'],['deadbug','2–3 × 8 / бік'],['bridge','2 × 12'],['posture','2 × 8 / бік']]},
 {id:'home-band-legs',name:'Ноги з міністрічкою',place:'home',goal:'strength',gear:'band',level:'all',minutes:32,tone:'peach',tag:'Міністрічка',items:[['lateralband','2 × 10 кроків / бік'],['squat','3 × 8–12'],['bridge','3 × 12'],['calf','2 × 12']]},
 {id:'home-band-upper',name:'Верх тіла зі стрічкою',place:'home',goal:'muscle',gear:'band',level:'all',minutes:34,tone:'blue',tag:'Довга стрічка',items:[['rowband','3 × 8–12'],['bandpress','3 × 8–12'],['pullapart','2 × 10–12'],['bird','2 × 8 / бік']]},
 {id:'home-dumbbell-legs',name:'Гантелі · день ніг',place:'home',goal:'muscle',gear:'dumbbell',level:'all',minutes:40,tone:'peach',tag:'Ноги й сідниці',items:[['goblet','3 × 8–12'],['hinge','3 × 8–12'],['split','2 × 8 / нога'],['farmer','2 × 30–45 с']]},
 {id:'home-dumbbell-upper',name:'Гантелі · верх тіла',place:'home',goal:'muscle',gear:'dumbbell',level:'all',minutes:38,tone:'violet',tag:'Спина, груди, плечі',items:[['dbrow','3 × 8–12 / рука'],['dbfloor','3 × 8–12'],['press','2 × 8–12'],['dbreverse','2 × 10–12']]},
 {id:'gym-push',name:'Зал · груди та плечі',place:'gym',goal:'muscle',gear:'machine',level:'all',minutes:45,tone:'blue',tag:'Верх тіла',items:[['chest','3 × 8–12'],['cableface','2 × 10–12'],['press','2–3 × 8–12'],['deadbug','2 × 8 / бік']]},
 {id:'gym-pull',name:'Зал · спина й тяги',place:'gym',goal:'strength',gear:'machine',level:'all',minutes:45,tone:'lime',tag:'Верх тіла',items:[['lat','3 × 8–12'],['seatedrow','3 × 8–12'],['cableface','2 × 10–12'],['curl','2 × 8–12']]},
 {id:'gym-leg-mix',name:'Зал · ноги без поспіху',place:'gym',goal:'strength',gear:'machine',level:'all',minutes:48,tone:'peach',tag:'Тренажери',items:[['legpress','3 × 8–12'],['hamcurl','3 × 8–12'],['extension','2 × 8–12'],['calf','2 × 12']]},
 {id:'gym-bike',name:'Велотренажер · рівний темп',place:'gym',goal:'cardio',gear:'machine',level:'beginner',minutes:25,tone:'violet',tag:'М’яке кардіо',items:[['bike','5 хв легко'],['bike','15 хв помірно'],['bike','5 хв легко']]},
 {id:'out-walk',name:'30 хв швидкої ходьби',place:'outdoor',goal:'cardio',gear:'none',level:'all',minutes:30,tone:'lime',tag:'Прогулянка',items:[['walk','5 хв легко'],['walk','20 хв жваво'],['walk','5 хв легко']]},
 {id:'out-long',name:'Довша прогулянка',place:'outdoor',goal:'cardio',gear:'none',level:'all',minutes:45,tone:'blue',tag:'Витривалість',items:[['walk','5 хв легко'],['walk','35 хв комфортно'],['walk','5 хв легко']]},
 {id:'out-interval',name:'Ходьба з короткими прискореннями',place:'outdoor',goal:'cardio',gear:'none',level:'all',minutes:28,tone:'peach',tag:'Зміна темпу',items:[['walk','5 хв легко'],['walk','6 × 1 хв жваво + 2 хв спокійно'],['walk','5 хв легко']]},
 {id:'home-recovery',name:'Відновлення і рухливість',place:'home',goal:'start',gear:'none',level:'beginner',minutes:18,tone:'violet',tag:'День без силового навантаження',items:[['mobility','5 хв'],['posture','2 × 6 / бік'],['breathing','3 хв']]}
);

const TRAINING_DRAFT_KEY='daymark-training-draft-v1';
const TRAINING_PREF_KEY='daymark-training-preferences-v1';
let trainingPrefs={goal:goal()?.kind==='lose'?'lose':'maintain',place:'home',gear:'none',level:'beginner',time:30,energy:'okay',likes:'mixed',frequency:3,limitations:'none',setup:false};
try{const p=JSON.parse(localStorage.getItem(TRAINING_PREF_KEY));if(p&&typeof p==='object')for(const [k,allowed] of Object.entries({goal:['form','lose','maintain','muscle','strength','cardio','start'],place:['home','gym','outdoor','all'],gear:['none','band','dumbbell','machine','all'],level:['beginner','regular'],time:[15,20,30,45,60],energy:['okay','low'],likes:['mixed','walking','strength','cardio'],frequency:[2,3,4,5],limitations:['none','unsure','medical'],setup:[true,false]}))if(allowed.includes(p[k]))trainingPrefs[k]=p[k];}catch{}
let trainingRun=null;
try{const d=JSON.parse(localStorage.getItem(TRAINING_DRAFT_KEY)),plan=TRAINING_PLANS.find(p=>p.id===d?.id);if(plan&&d.date===today()&&['warmup','exercise','rest','cooldown'].includes(d.phase)&&Number.isInteger(d.index)&&d.index>=0&&d.index<plan.items.length&&Number.isInteger(d.set)&&d.set>=1&&d.set<=6&&Number.isFinite(d.activeMs)&&d.activeMs>=0&&d.activeMs<86400000&&Number.isInteger(d.done)&&d.done>=0&&d.done<=70&&Number.isFinite(d.startedAt)&&d.startedAt>0&&d.startedAt<=Date.now()){trainingRun={...d,paused:true,activeSince:null,restUntil:null};}else if(d)localStorage.removeItem(TRAINING_DRAFT_KEY);}catch{}
const trainingPlan=id=>TRAINING_PLANS.find(p=>p.id===id);
const trainingStrength=p=>!['cardio','start'].includes(p.goal)&&p.id!=='reset';
function trainingHistory(){return Object.entries(state.logs).flatMap(([date,l])=>(l.workouts||[]).filter(w=>w.programId).map(w=>({date,id:w.programId}))).sort((a,b)=>b.date.localeCompare(a.date));}
function trainingScore(p,prefs){const reasons=[];let score=0;
 if(prefs.place!=='all'&&p.place!==prefs.place)return null;
 if(prefs.gear!=='all'&&p.gear!==prefs.gear)return null;
 const goalMatch=prefs.goal==='form'?['strength','cardio'].includes(p.goal):prefs.goal==='start'?p.goal==='start':p.goal===prefs.goal;
 if(goalMatch){score+=6;reasons.push('відповідає твоїй цілі');}
 else if(prefs.goal==='form'&&p.goal==='start'){score+=2;reasons.push('комфортний старт');}
 if(p.level==='beginner'&&prefs.level==='beginner'){score+=3;reasons.push('підходить для початку');}
 if(p.level==='all'&&prefs.level==='regular')score+=2;
 if(p.minutes<=Number(prefs.time)){score+=2;reasons.push('вкладається у '+prefs.time+' хв');}
 else score-=Math.min(6,Math.ceil((p.minutes-Number(prefs.time))/5));
 const history=trainingHistory();const last=history.find(w=>w.id===p.id);
 if(last&&diff(last.date,today())>=0&&diff(last.date,today())<=6){score-=3;reasons.push('цю програму вже робили нещодавно');}
 const recentStrength=history.some(w=>diff(w.date,today())>=0&&diff(w.date,today())<2&&trainingStrength(trainingPlan(w.id)||{}));
 if(recentStrength&&trainingStrength(p)){score-=4;reasons.push('після недавньої силової варто оцінити відновлення');}
 if(prefs.energy==='low'){if(['home-recovery','reset','walk-easy','home-quiet'].includes(p.id)){score+=7;reasons.push('сьогодні хочеться легшого руху');}else if(trainingStrength(p)){score-=6;}}
 if(state.logs[today()]?.sleep?.quality==='tired'&&trainingStrength(p)){score-=2;reasons.push('ти відзначив / відзначила втому після сну');}
 return{plan:p,score,reasons};}
function trainingRecommend(){return TRAINING_PLANS.map(p=>trainingScore(p,trainingPrefs)).filter(Boolean).sort((a,b)=>b.score-a.score||a.plan.minutes-b.plan.minutes)[0]||null;}
function trainingSelect(name,options){return '<label>'+name+'<select data-training-pref="'+options[0]+'">'+options.slice(1).map(([id,text])=>'<option value="'+id+'" '+(String(trainingPrefs[options[0]])===String(id)?'selected':'')+'>'+text+'</option>').join('')+'</select></label>';}
function trainingCoachPanel(){const r=trainingRecommend(),p=r?.plan,paused=trainingRun?.paused;return '<section class="training-coach-panel"><div class="training-coach-top"><span>🏋️ РОЗУМНИЙ ПІДБІР · БЕЗ AI-ЧАТУ</span><h3>Що підійде тобі сьогодні?</h3><p>Розкажи про свій день. Ми зіставимо ціль, інвентар, час і попередні записи — та покажемо логіку вибору.</p></div><div class="training-preferences">'+trainingSelect('Моя ціль',['goal',['form','Бути у формі / схуднути'],['muscle','Набрати м’язи'],['strength','Стати сильніше'],['cardio','Розвинути витривалість'],['start','Повернутися до руху']])+trainingSelect('Де я зараз',['place',['home','Вдома'],['gym','У залі'],['outdoor','Надворі'],['all','Неважливо']])+trainingSelect('Мій інвентар',['gear',['none','Без інвентарю'],['band','Резинка / еспандер'],['dumbbell','Гантелі'],['machine','Тренажери'],['all','Будь-який']])+trainingSelect('Досвід',['level',['beginner','Починаю / повертаюсь'],['regular','Тренуюсь регулярно']])+trainingSelect('Є часу',['time',['15','15 хв'],['20','20 хв'],['30','30 хв'],['45','45 хв'],['60','60 хв']])+trainingSelect('Сили сьогодні',['energy',['okay','Звичайний день'],['low','Хочу легше']])+'</div>'+(p?'<div class="training-coach-match"><span>ПІДІБРАНО ДЛЯ ТЕБЕ ↗</span><h4>'+p.name+'</h4><p>'+p.minutes+' хв · '+p.tag+'. '+(r.reasons.filter(x=>!x.includes('недавньої')&&!x.includes('втому')).slice(0,2).join('; ')||'Можеш змінити вибір нижче')+'.</p>'+(r.reasons.some(x=>x.includes('недавньої')||x.includes('втому'))?'<small>Ти нещодавно тренувався / тренувалась або відзначив / відзначила втому. Оціни самопочуття й за потреби обери легший день.</small>':'')+'<button data-action="training-open" data-id="'+p.id+'">Відкрити план <b>↗</b></button></div>':'<div class="training-coach-match"><h4>Під таку комбінацію поки немає плану</h4><p>Зміни місце або інвентар. Жодних випадкових призначень.</p></div>')+(paused?'<button class="training-resume" data-action="training-flow-resume">▶ Продовжити незавершене тренування <b>↗</b></button><button class="training-discard" data-action="training-flow-discard">Скасувати незавершене тренування</button>':'')+'<p class="training-coach-disclaimer">Це підбір за зрозумілими правилами, не діагностика й не персональне призначення. За травми, вагітності чи медичних обмежень узгодь план з фахівцем.</p></section>';}
const baseTrainingStudioFlow=trainingStudio;
trainingStudio=function(){return baseTrainingStudioFlow().replace('<div class="training-filter-group">',trainingCoachPanel()+'<div class="training-filter-group">').replace('15–45 хв','15–48 хв');};
sportHomeCard=function(){return '<button class="sport-home-card" data-action="training-home"><span class="sport-home-icon">'+dumbbellArt()+'</span><span><small>DAYMARK TRAINING · '+TRAINING_PLANS.length+' ПРОГРАМ</small><strong>Тренування під твій день</strong><em>Розумний підбір · дім, зал, ходьба й біг</em></span><b>↗</b></button>';};

const baseVictoryCalendarFlow=victoryCalendar;
victoryCalendar=function(g,ym,weekOnly=false){let html=baseVictoryCalendarFlow(g,ym,weekOnly);for(const[d,l]of Object.entries(state.logs)){if(l.workouts?.some(w=>w.programId)){html=html.replace('data-date="'+d+'"','data-date="'+d+'" data-training="true"');}}return html;};

function trainingSetCount(item){const m=item[1].match(/^(\d+)(?:–(\d+))?\s*×/);if(!m)return 1;const n=m[2]&&trainingPrefs.level==='regular'?Number(m[2]):Number(m[1]);return Math.max(1,Math.min(n,6));}
function trainingTargetSeconds(item){const prescription=item[1].replace(/^\d+(?:–\d+)?\s*×\s*/,''),parts=[...prescription.matchAll(/(\d+)\s*хв/g)];return parts.length?parts.reduce((sum,m)=>sum+Number(m[1]),0)*60:0;}
function trainingTotalSets(p){return p.items.reduce((sum,item)=>sum+trainingSetCount(item),0);}
function trainingTimedStages(p){return p.items.length>=3&&p.items.every(item=>trainingTargetSeconds(item)>0);}
function trainingActiveMs(){return (trainingRun?.activeMs||0)+(trainingRun&&!trainingRun.paused&&trainingRun.activeSince?Math.max(0,Date.now()-trainingRun.activeSince):0);}
function trainingClock(ms){const seconds=Math.floor(ms/1000);return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function trainingSaveDraft(){if(!trainingRun||trainingRun.phase==='complete'){localStorage.removeItem(TRAINING_DRAFT_KEY);return;}const snapshot={...trainingRun,activeMs:trainingActiveMs(),activeSince:null,paused:true,restUntil:null};try{localStorage.setItem(TRAINING_DRAFT_KEY,JSON.stringify(snapshot));}catch{}}
function trainingPause(){if(!trainingRun||trainingRun.phase==='complete'||trainingRun.paused)return;trainingRun.activeMs=trainingActiveMs();trainingRun.activeSince=null;trainingRun.paused=true;if(trainingRun.phase==='rest')trainingRun.restLeft=Math.max(0,Math.ceil((trainingRun.restUntil-Date.now())/1000));trainingRun.restUntil=null;trainingSaveDraft();}
function trainingResume(){if(!trainingRun||trainingRun.date!==today()){trainingRun=null;return;}trainingRun.paused=false;trainingRun.activeSince=Date.now();if(trainingRun.phase==='rest')trainingRun.restUntil=Date.now()+(trainingRun.restLeft||0)*1000;trainingFlowRender();}
function trainingStart(id){const p=trainingPlan(id);if(!p)return;if(trainingRun&&trainingRun.phase!=='complete'){if(!confirm('Незавершене тренування буде замінено новим. Почати іншу програму?'))return;}selectedDate=today();trainingRun={id,date:today(),phase:trainingTimedStages(p)?'exercise':'warmup',index:0,set:1,done:0,skipped:0,activeMs:0,activeSince:Date.now(),paused:false,restLeft:60,restUntil:null,stepActiveStart:0,startedAt:Date.now()};trainingSession={id};trainingSaveDraft();trainingFlowRender();}
function trainingFlowRender(){const r=trainingRun,p=trainingPlan(r?.id);if(!r||!p)return;const item=p.items[r.index],x=item&&TRAINING_EXERCISES[item[0]],total=trainingTotalSets(p);let body='';
 if(r.phase==='warmup')body='<div class="flow-stage warm"><span>00 / ПІДГОТОВКА</span><h2>Почни з розминки.</h2><p>5 хвилин легкого руху в комфортному темпі: пройдися, порухай плечима й суглобами. Не потрібно поспішати.</p><div class="flow-orb">↗</div><button class="flow-primary" data-action="training-flow-next">Я розім’ялась / розім’явся →</button></div>';
 if(r.phase==='exercise'){const target=trainingTargetSeconds(item),stepCue=target?'Твій відрізок: '+item[1].replace(/^\d+(?:–\d+)?\s*×\s*/,'')+'. Якщо некомфортно — сповільнись.':x.cue;body='<div class="flow-stage exercise"><span>ВПРАВА '+(r.index+1)+' / '+p.items.length+' · ПІДХІД '+r.set+' / '+trainingSetCount(item)+'</span><h2>'+x.name+'</h2><p class="flow-prescription">'+item[1]+' · '+x.group+'</p>'+(target?'<div class="flow-target">ТРИВАЛІСТЬ ВІДРІЗКА <b id="flowStepClock">'+trainingClock(Math.max(0,target*1000-(trainingActiveMs()-(r.stepActiveStart||0))))+'</b><small>Таймер підказує орієнтир; підтвердь виконання сама / сам.</small></div>':'')+trainingFigure(x.pose)+'<div class="flow-instruction"><b>ЗРОБИ ЗАРАЗ</b><p>'+stepCue+'</p></div><div class="flow-safety"><b>ТЕХНІКА</b><p>'+x.check+'</p></div><button class="flow-primary" data-action="training-flow-next">'+(target?'Відрізок виконано': 'Підхід виконано')+' ✓</button><button class="flow-secondary" data-action="training-flow-skip">Пропустити вправу</button></div>';}
 if(r.phase==='rest')body='<div class="flow-stage rest"><span>ПАУЗА / ВІДНОВЛЕННЯ</span><h2>Видихни.<br>Ти в процесі.</h2><div class="flow-rest-clock" id="flowRestClock">'+trainingClock((r.restLeft||0)*1000)+'</div><p>Наступний підхід відкриється після відліку. Можеш перейти раніше або зберегти тренування на паузі, якщо потрібен довший відпочинок.</p><button class="flow-primary" data-action="training-flow-next">Я готова / готовий далі →</button></div>';
 if(r.phase==='cooldown')body='<div class="flow-stage cool"><span>ФІНАЛЬНИЙ КРОК</span><h2>Сильна робота.<br>Тепер сповільнись.</h2><p>Кілька хвилин легкої ходьби або спокійного руху. Віднови дихання. Сьогоднішнє тренування вже зроблено — його не треба «заслужити» додатковим навантаженням.</p><div class="flow-orb">💪</div><button class="flow-primary" data-action="training-flow-next">Завершити тренування ✓</button></div>';
 if(r.phase==='complete')body='<div class="flow-finish"><span>DAYMARK / ТРЕНУВАННЯ В ІСТОРІЇ</span><div class="flow-finish-star">🏆</div><h2>Ти зробила / зробив це!</h2><p>Тренування записане у «Мій рух», а сьогодні в календарі з’явилась позначка тренування.</p><div><b>'+r.savedMinutes+' хв</b><b>'+r.done+' підходів</b></div><button class="flow-primary" data-action="training-flow-calendar">Побачити календар ↗</button><button class="flow-secondary" data-action="training-flow-diary">Мій рух і запис</button><small>Позначка тренування не закреслює автоматично всю денну ціль.</small></div>';
 const progress=Math.min(100,Math.round((r.done/Math.max(1,total))*100));openModal('DAYMARK TRAINING / '+p.name.toUpperCase(),'<div class="flow-shell"><div class="flow-top"><span>🏃 '+p.name+'</span><b id="flowElapsed">'+trainingClock(trainingActiveMs())+'</b></div><div class="flow-progress"><i style="width:'+progress+'%"></i></div><div class="flow-progress-caption"><span>'+(r.phase==='complete'?'ЗАВЕРШЕНО':r.phase==='warmup'?'РОЗМИНКА':r.phase==='cooldown'?'ЗАВЕРШЕННЯ':r.phase==='rest'?'ПАУЗА':'РУХ У ПРОЦЕСІ')+'</span><span>'+r.done+' / '+total+' підходів</span></div>'+body+(r.phase!=='complete'?'<button class="flow-pause" data-action="training-flow-pause">Ⅱ Зберегти й поставити на паузу</button>':'')+'</div>');$('modal').classList.add('training-player-dialog');trainingSaveDraft();}
function trainingFlowNext(){const r=trainingRun,p=trainingPlan(r?.id);if(!r||r.paused||!p)return;
 if(r.phase==='warmup'){r.phase='exercise';r.stepActiveStart=trainingActiveMs();}
 else if(r.phase==='exercise'){const item=p.items[r.index],timed=trainingTargetSeconds(item)>0;r.done++;if(r.set<trainingSetCount(item)){r.set++;if(timed){r.stepActiveStart=trainingActiveMs();}else{r.phase='rest';r.restLeft=trainingPrefs.level==='beginner'?60:90;r.restUntil=Date.now()+r.restLeft*1000;}}
 else if(r.index<p.items.length-1){r.index++;r.set=1;if(timed||trainingTargetSeconds(p.items[r.index])>0){r.stepActiveStart=trainingActiveMs();}else{r.phase='rest';r.restLeft=60;r.restUntil=Date.now()+60000;}}
 else if(trainingTimedStages(p)){trainingFlowComplete();return;}
 else r.phase='cooldown';}
 else if(r.phase==='rest'){r.phase='exercise';r.restUntil=null;r.restLeft=0;r.stepActiveStart=trainingActiveMs();}
 else if(r.phase==='cooldown'){trainingFlowComplete();return;}
 trainingFlowRender();}
function trainingFlowSkip(){const r=trainingRun,p=trainingPlan(r?.id);if(!r||r.phase!=='exercise'||!p)return;r.skipped++;if(r.index<p.items.length-1){r.index++;r.set=1;r.phase='exercise';r.stepActiveStart=trainingActiveMs();}else if(trainingTimedStages(p)){trainingFlowComplete();return;}else r.phase='cooldown';trainingFlowRender();}
function trainingFlowComplete(){const r=trainingRun,p=trainingPlan(r?.id);if(!r||!p||r.phase==='complete')return;if(!r.done){trainingRun=null;trainingSession=null;trainingSaveDraft();$('modal').classList.remove('training-player-dialog');closeModal();render();toast('Вправи не виконано — запис у календар не додано.');return;}const minutes=Math.max(1,Math.min(360,Math.round(trainingActiveMs()/60000)));const l=log(r.date);if(l.workouts.length>=100){toast('У цьому дні вже 100 активностей. Видали зайвий запис у щоденнику.');return;}l.workouts.push({id:uid(),name:p.name,programId:p.id,minutes,activityId:null,source:'manual',activeKcal:null,grossKcal:null,weight:null,met:null,distance:null,startTime:new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Kyiv',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(r.startedAt)),notes:r.done+' підходів · '+r.skipped+' пропущено',countEnergy:false});l.habits.move=true;r.activeMs=trainingActiveMs();r.activeSince=null;r.paused=true;r.phase='complete';r.savedMinutes=minutes;trainingTab='diary';persist();trainingSaveDraft();trainingFlowRender();}
function trainingFlowLeave(where){const d=trainingRun?.date;trainingRun=null;trainingSession=null;trainingSaveDraft();$('modal').classList.remove('training-player-dialog');closeModal();selectedDate=d||today();navigate(where);}
function trainingFlowDiscard(){if(!trainingRun)return;if(!confirm('Скасувати незавершене тренування? Запис у щоденник не додасться.'))return;trainingRun=null;trainingSession=null;trainingSaveDraft();$('modal').classList.remove('training-player-dialog');closeModal();render();}
actions['training-flow-next']=trainingFlowNext;
actions['training-flow-skip']=trainingFlowSkip;
actions['training-flow-pause']=()=>{trainingPause();$('modal').classList.remove('training-player-dialog');closeModal();render();toast('Тренування на паузі — повернися, коли зручно.');};
actions['training-flow-resume']=trainingResume;
actions['training-flow-discard']=trainingFlowDiscard;
actions['training-flow-calendar']=()=>trainingFlowLeave('journey');
actions['training-flow-diary']=()=>trainingFlowLeave('move');
actions['training-start']=b=>trainingStart(b.dataset.id);
actions['training-return']=()=>{if(trainingRun&&trainingRun.phase!=='complete')trainingFlowRender();else trainingSessionRender();};
document.addEventListener('change',e=>{const key=e.target.dataset?.trainingPref;if(!key)return;const value=e.target.value;if(!['goal','place','gear','level','time','energy'].includes(key))return;trainingPrefs[key]=key==='time'?Number(value):value;if(key==='place'&&value==='gym'&&trainingPrefs.gear==='none')trainingPrefs.gear='machine';if(key==='place'&&value==='outdoor')trainingPrefs.gear='none';try{localStorage.setItem(TRAINING_PREF_KEY,JSON.stringify(trainingPrefs));}catch{}render();});
document.getElementById('modal').addEventListener('close',()=>{if($('modal').classList.contains('training-player-dialog')){trainingPause();$('modal').classList.remove('training-player-dialog');if(currentView==='move')render();}});
$('modal').addEventListener('close',()=>{if(trainingRun&&trainingRun.phase!=='complete'&&!trainingRun.paused){trainingPause();$('modal').classList.remove('training-player-dialog');render();toast('Тренування збережено на паузі.');}});
setInterval(()=>{if(!trainingRun||trainingRun.paused||!$('modal').open)return;const clock=$('flowElapsed');if(clock)clock.textContent=trainingClock(trainingActiveMs());if(trainingRun.phase==='exercise'){const target=trainingTargetSeconds(trainingPlan(trainingRun.id)?.items[trainingRun.index]||['','']),display=$('flowStepClock');if(target&&display)display.textContent=trainingClock(Math.max(0,target*1000-(trainingActiveMs()-(trainingRun.stepActiveStart||0))));}if(trainingRun.phase==='rest'){const left=Math.max(0,Math.ceil((trainingRun.restUntil-Date.now())/1000)),display=$('flowRestClock');if(display)display.textContent=trainingClock(left*1000);if(left===0)trainingFlowNext();}},1000);
